class Codec {
    public String encode(List<String> strs) {
        StringBuilder out = new StringBuilder();
        for (String s : strs) out.append(s.length()).append('#').append(s);
        return out.toString();
    }
    public List<String> decode(String text) {
        List<String> out = new ArrayList<>();
        int i = 0;
        while (i < text.length()) {
            int hash = text.indexOf('#', i);
            int length = Integer.parseInt(text.substring(i, hash));
            int start = hash + 1;
            out.add(text.substring(start, start + length));
            i = start + length;
        }
        return out;
    }
}

