class DetectSquares {
    private final Map<Integer, Map<Integer, Integer>> rows = new HashMap<>();
    public void add(int[] point) {
        rows.computeIfAbsent(point[1], y -> new HashMap<>()).merge(point[0], 1, Integer::sum);
    }
    private int countAt(int x, int y) {
        Map<Integer, Integer> row = rows.get(y);
        return row == null ? 0 : row.getOrDefault(x, 0);
    }
    public int count(int[] point) {
        int x = point[0], y = point[1], answer = 0;
        Map<Integer, Integer> row = rows.get(y);
        if (row == null) return 0;
        for (Map.Entry<Integer, Integer> e : row.entrySet()) {
            int otherX = e.getKey(), side = otherX - x;
            if (side == 0) continue;
            answer += e.getValue() * countAt(x, y + side) * countAt(otherX, y + side);
            answer += e.getValue() * countAt(x, y - side) * countAt(otherX, y - side);
        }
        return answer;
    }
}

