public List<Integer> findSubstring(String s, String[] words) {
    List<Integer> out = new ArrayList<>();
    if (words.length == 0) return out;
    int width = words[0].length();
    Map<String, Integer> need = new HashMap<>();
    for (String word : words) need.merge(word, 1, Integer::sum);
    for (int offset = 0; offset < width && offset < s.length(); offset++) {
        Map<String, Integer> have = new HashMap<>();
        int left = offset, used = 0;
        for (int right = offset; right + width <= s.length(); right += width) {
            String word = s.substring(right, right + width);
            if (!need.containsKey(word)) { have.clear(); used = 0; left = right + width; continue; }
            have.merge(word, 1, Integer::sum); used++;
            while (have.get(word) > need.get(word)) {
                String old = s.substring(left, left + width);
                have.put(old, have.get(old) - 1); left += width; used--;
            }
            if (used == words.length) {
                out.add(left);
                String old = s.substring(left, left + width);
                have.put(old, have.get(old) - 1); left += width; used--;
            }
        }
    }
    return out;
}

