public int maxSubarraySumCircular(int[] nums) {
    int n = nums.length;
    long[] prefix = new long[2 * n + 1];
    for (int i = 0; i < 2 * n; i++) prefix[i + 1] = prefix[i] + nums[i % n];
    Deque<Integer> deque = new ArrayDeque<>(); deque.addLast(0);
    long best = Long.MIN_VALUE;
    for (int end = 1; end <= 2 * n; end++) {
        while (deque.peekFirst() < end - n) deque.removeFirst();
        best = Math.max(best, prefix[end] - prefix[deque.peekFirst()]);
        while (!deque.isEmpty() && prefix[deque.peekLast()] >= prefix[end]) deque.removeLast();
        deque.addLast(end);
    }
    return (int) best;
}

