    int n = board.length; boolean[] seen = new boolean[n * n + 1];
    Queue<Integer> queue = new ArrayDeque<>(); queue.offer(1); seen[1] = true; int rolls = 0;
    while (!queue.isEmpty()) {
        for (int size = queue.size(); size > 0; size--) {
            int square = queue.poll(); if (square == n * n) return rolls;
            for (int next = square + 1; next <= Math.min(square + 6, n * n); next++) {
                int band = (next - 1) / n, col = (next - 1) % n;
                if (band % 2 == 1) col = n - 1 - col;
                int value = board[n - 1 - band][col], destination = value == -1 ? next : value;
                if (!seen[destination]) { seen[destination] = true; queue.offer(destination); }
            }
        }
        rolls++;
    }
    return -1;
}

