public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
    Map<String, Map<String, Double>> graph = new HashMap<>();
    for (int i = 0; i < values.length; i++) {
        String a = equations.get(i).get(0), b = equations.get(i).get(1);
        graph.computeIfAbsent(a, x -> new HashMap<>()).put(b, values[i]);
        graph.computeIfAbsent(b, x -> new HashMap<>()).put(a, 1.0 / values[i]);
    }
    double[] out = new double[queries.size()];
    for (int i = 0; i < out.length; i++) {
        String a = queries.get(i).get(0), b = queries.get(i).get(1);
        out[i] = graph.containsKey(a) && graph.containsKey(b) ? ratio(a, b, graph, new HashSet<>()) : -1.0;
    }
    return out;
}
private double ratio(String a, String b, Map<String, Map<String, Double>> graph, Set<String> seen) {
    if (a.equals(b)) return 1.0;
    seen.add(a);
    for (Map.Entry<String, Double> e : graph.get(a).entrySet()) {
        if (seen.contains(e.getKey())) continue;
        double result = ratio(e.getKey(), b, graph, seen);
        if (result >= 0) return e.getValue() * result;
    }
    return -1.0;
}

