public String alienOrder(String[] words) {
    List<Set<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < 26; i++) graph.add(new HashSet<>());
    boolean[] present = new boolean[26]; int[] indegree = new int[26]; int total = 0;
    for (String word : words) for (char c : word.toCharArray()) if (!present[c - 'a']) { present[c - 'a'] = true; total++; }
    for (int i = 1; i < words.length; i++) {
        String a = words[i - 1], b = words[i]; int j = 0;
        while (j < a.length() && j < b.length() && a.charAt(j) == b.charAt(j)) j++;
        if (j == b.length() && a.length() > b.length()) return "";
        if (j < a.length() && j < b.length()) {
            int u = a.charAt(j) - 'a', v = b.charAt(j) - 'a';
            if (graph.get(u).add(v)) indegree[v]++;
        }
    }
    Queue<Integer> queue = new ArrayDeque<>();
    for (int i = 0; i < 26; i++) if (present[i] && indegree[i] == 0) queue.offer(i);
    StringBuilder out = new StringBuilder();
    while (!queue.isEmpty()) {
        int u = queue.poll(); out.append((char) ('a' + u));
        for (int v : graph.get(u)) if (--indegree[v] == 0) queue.offer(v);
    }
    return out.length() == total ? out.toString() : "";
}

