public int longestIncreasingPath(int[][] matrix) {
    if (matrix.length == 0) return 0;
    int[][] memo = new int[matrix.length][matrix[0].length]; int best = 0;
    for (int r = 0; r < matrix.length; r++) for (int c = 0; c < matrix[0].length; c++) best = Math.max(best, length(matrix, memo, r, c));
    return best;
}
private int length(int[][] a, int[][] memo, int r, int c) {
    if (memo[r][c] != 0) return memo[r][c];
    int best = 1; int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int[] d : dirs) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < a.length && nc >= 0 && nc < a[0].length && a[nr][nc] > a[r][c]) best = Math.max(best, 1 + length(a, memo, nr, nc));
    }
    return memo[r][c] = best;
}

