public List<String> findItinerary(List<List<String>> tickets) {
    Map<String, PriorityQueue<String>> graph = new HashMap<>();
    for (List<String> ticket : tickets) graph.computeIfAbsent(ticket.get(0), k -> new PriorityQueue<>()).offer(ticket.get(1));
    Deque<String> stack = new ArrayDeque<>(); LinkedList<String> route = new LinkedList<>(); stack.push("JFK");
    while (!stack.isEmpty()) {
        PriorityQueue<String> next = graph.get(stack.peek());
        if (next != null && !next.isEmpty()) stack.push(next.poll());
        else route.addFirst(stack.pop());
    }
    return route;
}

