public int swimInWater(int[][] grid) {
    int n = grid.length; int[][] best = new int[n][n];
    for (int[] row : best) Arrays.fill(row, Integer.MAX_VALUE);
    best[0][0] = grid[0][0];
    PriorityQueue<int[]> heap = new PriorityQueue<>((a,b) -> Integer.compare(a[0],b[0]));
    heap.offer(new int[]{grid[0][0],0,0}); int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    while (!heap.isEmpty()) {
        int[] p = heap.poll(); int time = p[0], r = p[1], c = p[2];
        if (time != best[r][c]) continue;
        if (r == n - 1 && c == n - 1) return time;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
            int next = Math.max(time, grid[nr][nc]);
            if (next < best[nr][nc]) { best[nr][nc] = next; heap.offer(new int[]{next,nr,nc}); }
        }
    }
    return -1;
}

