public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
    int infinity = 1_000_000_000; int[] cost = new int[n];
    Arrays.fill(cost, infinity); cost[src] = 0;
    for (int round = 0; round <= k; round++) {
        int[] next = cost.clone();
        for (int[] flight : flights) {
            if (cost[flight[0]] != infinity) next[flight[1]] = Math.min(next[flight[1]], cost[flight[0]] + flight[2]);
        }
        cost = next;
    }
    return cost[dst] == infinity ? -1 : cost[dst];
}

