public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
    Integer[] order = new Integer[profits.length];
    for (int i = 0; i < order.length; i++) order[i] = i;
    Arrays.sort(order, (a,b) -> Integer.compare(capital[a], capital[b]));
    PriorityQueue<Integer> available = new PriorityQueue<>(Comparator.reverseOrder());
    int i = 0;
    for (int step = 0; step < k; step++) {
        while (i < order.length && capital[order[i]] <= w) available.offer(profits[order[i++]]);
        if (available.isEmpty()) break;
        w += available.poll();
    }
    return w;
}

