public List<List<Integer>> combinationSum2(int[] candidates, int target) {
    Arrays.sort(candidates); List<List<Integer>> out = new ArrayList<>();
    search(candidates, 0, target, new ArrayList<>(), out); return out;
}
private void search(int[] a, int start, int remaining, List<Integer> path, List<List<Integer>> out) {
    if (remaining == 0) { out.add(new ArrayList<>(path)); return; }
    for (int i = start; i < a.length && a[i] <= remaining; i++) {
        if (i > start && a[i] == a[i - 1]) continue;
        path.add(a[i]); search(a, i + 1, remaining - a[i], path, out); path.remove(path.size() - 1);
    }
}

