public List<List<String>> partition(String s) {
    int n = s.length(); boolean[][] pal = new boolean[n][n];
    for (int left = n - 1; left >= 0; left--) for (int right = left; right < n; right++) {
        pal[left][right] = s.charAt(left) == s.charAt(right) && (right - left < 2 || pal[left + 1][right - 1]);
    }
    List<List<String>> out = new ArrayList<>(); split(s, 0, pal, new ArrayList<>(), out); return out;
}
private void split(String s, int start, boolean[][] pal, List<String> path, List<List<String>> out) {
    if (start == s.length()) { out.add(new ArrayList<>(path)); return; }
    for (int end = start; end < s.length(); end++) if (pal[start][end]) {
        path.add(s.substring(start, end + 1)); split(s, end + 1, pal, path, out); path.remove(path.size() - 1);
    }
}

