public List<List<String>> solveNQueens(int n) {
    char[][] board = new char[n][n]; for (char[] row : board) Arrays.fill(row, '.');
    List<List<String>> out = new ArrayList<>();
    searchQueens(0, board, new boolean[n], new boolean[2 * n], new boolean[2 * n], out); return out;
}

private void searchQueens(int row, char[][] board, boolean[] cols, boolean[] down, boolean[] up, List<List<String>> out) {
    int n = board.length;
    if (row == n) {
        List<String> answer = new ArrayList<>(); for (char[] line : board) answer.add(new String(line)); out.add(answer); return;
    }
    for (int col = 0; col < n; col++) {
        int d = row - col + n - 1, u = row + col;
        if (cols[col] || down[d] || up[u]) continue;
        cols[col] = down[d] = up[u] = true; board[row][col] = 'Q';
        searchQueens(row + 1, board, cols, down, up, out);
        board[row][col] = '.'; cols[col] = down[d] = up[u] = false;
    }
}

