private int count(int row, int n, boolean[] cols, boolean[] down, boolean[] up) {
    if (row == n) return 1;
    int result = 0;
    for (int col = 0; col < n; col++) {
        int d = row - col + n - 1, u = row + col;
        if (cols[col] || down[d] || up[u]) continue;
        cols[col] = down[d] = up[u] = true;
        result += count(row + 1, n, cols, down, up);
        cols[col] = down[d] = up[u] = false;
    }
    return result;
}

