private static class TrieNode { TrieNode[] next = new TrieNode[26]; String word; }
public List<String> findWords(char[][] board, String[] words) {
    TrieNode root = new TrieNode();
    for (String word : words) {
        TrieNode node = root;
        for (char c : word.toCharArray()) { int i = c - 'a'; if (node.next[i] == null) node.next[i] = new TrieNode(); node = node.next[i]; }
        node.word = word;
    }
    List<String> out = new ArrayList<>();
    for (int r = 0; r < board.length; r++) for (int c = 0; c < board[0].length; c++) find(board, r, c, root, out);
    return out;
}
private void find(char[][] board, int r, int c, TrieNode parent, List<String> out) {
    if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] == '#') return;
    char letter = board[r][c]; TrieNode node = parent.next[letter - 'a']; if (node == null) return;
    if (node.word != null) { out.add(node.word); node.word = null; }
    board[r][c] = '#';
    find(board, r+1, c, node, out); find(board, r-1, c, node, out); find(board, r, c+1, node, out); find(board, r, c-1, node, out);
    board[r][c] = letter;
}

