    return Math.max(linear(nums, 0, nums.length - 2), linear(nums, 1, nums.length - 1));
}
private int linear(int[] nums, int left, int right) {
    int previous = 0, current = 0;
    for (int i = left; i <= right; i++) { int next = Math.max(current, previous + nums[i]); previous = current; current = next; }
    return current;
}

