public int maxCoins(int[] nums) {
    int n = nums.length; int[] value = new int[n + 2]; value[0] = value[n + 1] = 1;
    for (int i = 0; i < n; i++) value[i + 1] = nums[i];
    int[][] dp = new int[n + 2][n + 2];
    for (int length = 1; length <= n; length++) for (int left = 1; left + length - 1 <= n; left++) {
        int right = left + length - 1;
        for (int last = left; last <= right; last++) {
            int score = dp[left][last - 1] + value[left - 1] * value[last] * value[right + 1] + dp[last + 1][right];
            dp[left][right] = Math.max(dp[left][right], score);
        }
    }
    return dp[1][n];
}

