public boolean isNStraightHand(int[] hand, int groupSize) {
    if (hand.length % groupSize != 0) return false;
    TreeMap<Integer, Integer> count = new TreeMap<>(); for (int x : hand) count.merge(x, 1, Integer::sum);
    while (!count.isEmpty()) {
        int start = count.firstKey();
        for (int i = 0; i < groupSize; i++) {
            int value = start + i; Integer frequency = count.get(value);
            if (frequency == null) return false;
            if (frequency == 1) count.remove(value); else count.put(value, frequency - 1);
        }
    }
    return true;
}

