public void gameOfLife(int[][] board) {
    if (board.length == 0) return;
    for (int r = 0; r < board.length; r++) for (int c = 0; c < board[0].length; c++) {
        int neighbors = 0;
        for (int dr = -1; dr <= 1; dr++) for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) continue;
            int nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length) neighbors += board[nr][nc] & 1;
        }
        if (neighbors == 3 || (neighbors == 2 && (board[r][c] & 1) == 1)) board[r][c] |= 2;
    }
    for (int[] row : board) for (int c = 0; c < row.length; c++) row[c] >>= 1;
}

