public List<String> fullJustify(String[] words, int maxWidth) {
    List<String> out = new ArrayList<>(); int start = 0;
    while (start < words.length) {
        int end = start, letters = 0;
        while (end < words.length && letters + words[end].length() + end - start <= maxWidth) letters += words[end++].length();
        int gaps = end - start - 1; StringBuilder line = new StringBuilder();
        if (end == words.length || gaps == 0) {
            for (int i = start; i < end; i++) { if (i > start) line.append(' '); line.append(words[i]); }
            while (line.length() < maxWidth) line.append(' ');
        } else {
            int spaces = maxWidth - letters, base = spaces / gaps, extra = spaces % gaps;
            for (int i = start; i < end; i++) {
                line.append(words[i]);
                if (i < end - 1) for (int j = 0; j < base + (i - start < extra ? 1 : 0); j++) line.append(' ');
            }
        }
        out.add(line.toString()); start = end;
    }
    return out;
}
